function CountEvenLength(lst: seq<string>): int
    requires lst != null
    ensures 0 <= CountEvenLength(lst) <= |lst|
{
    var count := 0;
    var i := 0;
    while i < |lst|
        invariant 0 <= count <= i
        invariant count == CountEvenLength(lst[0..i])
    {
        if lst[i].Length % 2 == 0 {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}

function SortedByLengthAndAlphabetical(s: seq<string>): bool
    requires s != null
{
    forall i, j: int :: 0 <= i < j < |s| ==> 
        (s[i].Length < s[j].Length || 
         (s[i].Length == s[j].Length && s[i] <= s[j]))
}
